/**
 * Turns a scenario into a planned context.
 *
 * Lives beside the metrics rather than inside a test file because the eval must
 * be runnable outside vitest — a baseline that can only be regenerated by a test
 * runner is a baseline nobody regenerates.
 */

import { extractFile } from "../symbols.js";
import {
  planContext,
  type AssembledContext,
  type ChangedFileInput,
} from "../planner.js";
import {
  computeMetrics,
  summarize,
  type PlannerMetrics,
  type PlannerReport,
} from "./metrics.js";
import type { PlannerScenario } from "./scenario.js";

/**
 * Default budget.
 *
 * Generous on purpose: the corpus measures *selection*, and a tight default
 * would make every scenario a budget test. Scenarios that mean to exercise
 * eviction set `budgetTokens` themselves.
 */
export const DEFAULT_EVAL_BUDGET_TOKENS = 100_000;

export function runScenario(scenario: PlannerScenario): AssembledContext {
  const sources = new Map(Object.entries(scenario.files));
  const changed: ChangedFileInput[] = scenario.changed.map((entry) => ({
    path: entry.path,
    content: scenario.files[entry.path] ?? "",
    changedLines: entry.changedLines,
  }));

  return planContext(
    {
      changed,
      repository: Object.entries(scenario.files).map(([path, source]) =>
        extractFile(path, source),
      ),
      sources,
      ...(scenario.instructions === undefined
        ? {}
        : { instructions: scenario.instructions }),
      ...(scenario.pathInstructions === undefined
        ? {}
        : { pathInstructions: scenario.pathInstructions }),
    },
    scenario.budgetTokens ?? DEFAULT_EVAL_BUDGET_TOKENS,
  );
}

export function evaluate(scenarios: readonly PlannerScenario[]): {
  readonly report: PlannerReport;
  readonly contexts: ReadonlyMap<string, AssembledContext>;
} {
  const contexts = new Map<string, AssembledContext>();
  const metrics: PlannerMetrics[] = [];

  for (const scenario of scenarios) {
    const context = runScenario(scenario);
    contexts.set(scenario.id, context);
    metrics.push(computeMetrics(scenario, context));
  }

  return { report: summarize(metrics), contexts };
}
